package com.dpworld.fms.mapimport;
import java.util.*;
public record TerminalOverrides(Set<Long>disabledRoads,Map<Long,String>directionOverrides,Map<Long,Double>speedOverrides,Map<Long,List<String>>vehicleRestrictions,List<PrivateNode>surveyedPrivateNodes,List<PrivateSegment>surveyedPrivateSegments,Map<String,String>parkingNodes,Map<String,String>chargingNodes,Map<String,String>fuelingNodes){public TerminalOverrides{disabledRoads=disabledRoads==null?Set.of():Set.copyOf(disabledRoads);directionOverrides=directionOverrides==null?Map.of():Map.copyOf(directionOverrides);speedOverrides=speedOverrides==null?Map.of():Map.copyOf(speedOverrides);vehicleRestrictions=vehicleRestrictions==null?Map.of():Map.copyOf(vehicleRestrictions);surveyedPrivateNodes=surveyedPrivateNodes==null?List.of():List.copyOf(surveyedPrivateNodes);surveyedPrivateSegments=surveyedPrivateSegments==null?List.of():List.copyOf(surveyedPrivateSegments);parkingNodes=parkingNodes==null?Map.of():Map.copyOf(parkingNodes);chargingNodes=chargingNodes==null?Map.of():Map.copyOf(chargingNodes);fuelingNodes=fuelingNodes==null?Map.of():Map.copyOf(fuelingNodes);}public static TerminalOverrides empty(){return new TerminalOverrides(null,null,null,null,null,null,null,null,null);}public record PrivateNode(String code,double latitude,double longitude){}public record PrivateSegment(String code,String from,String to,double speedKph,boolean oneWay,List<String>allowedAssetTypes){} }
